MATCH (p:Pod)-[:BelongsTo]->(ns:Namespace)
WHERE ns['metadata']['name'] = 'storefront'
  AND NOT EXISTS { MATCH (p)<-[:Manages]-(:Deployment) }
  AND NOT EXISTS { MATCH (p)<-[:Manages]-(:StatefulSet) }
  AND NOT EXISTS { MATCH (p)<-[:Manages]-(:DaemonSet) }
  AND NOT EXISTS { MATCH (p)<-[:Manages]-(:Job) }
  AND NOT EXISTS { MATCH (p)<-[:Manages]-(:ReplicaSet) }
RETURN p['metadata']['name'] AS pod_name, p['metadata']['namespace'] AS namespace

